            "denied": {
              "properties": {
                "rejection": {
                  "type": "string"
                }
              },
              "required": [
                "rejection"
              ],
              "type": "object"
            }
          },
          "required": [
            "denied"
          ],
          "title": "DeniedReviewDecision",
          "type": "object"
        },
        {
          "description": "Automatic approval review timed out before reaching a decision.",
          "enum": [
            "timed_out"
          ],
          "type": "string"
